import { compareVersions, VERSION_TEXT_UNPINNED_FIELD } from "./entity-versioning";
import type { GameLocale } from "./i18n";
import type { EntityFieldDiff, EntityVersionDiff, VersionedEntityType } from "./types";

/**
 * Each game locale's title and description template as they were at every
 * version from `pinnedFrom` on, taken from the game files of that version's
 * build (the build archive, see AGENTS.md).
 * Generated by scripts/generate-localization-history.ts.
 */
export interface LocalizationHistory {
  pinnedFrom: string;
  /** Build whose text each version was read from: an archive directory, or WORKTREE for the unarchived current version. */
  snapshots: { version: string; build: string }[];
  /** Change points per locale, type, id, and entity field: [version, value] oldest first. */
  text: Partial<Record<GameLocale, Partial<Record<VersionedEntityType, Record<string, Partial<Record<TrackedField, [string, string][]>>>>>>>;
  /**
   * Number changes the authored diffs recorded only inside the Korean baked
   * text. Recovered against the Korean template so every locale bakes them.
   */
  varDiffs: { entityType: VersionedEntityType; entityId: string; patch: string; field: string; before: number; after: number | null }[];
  /** Fields the site renders differently from the raw table, so history cannot stand in for them. */
  untracked: Partial<Record<GameLocale, Partial<Record<VersionedEntityType, string[]>>>>;
}

export type TrackedField = "name" | "descriptionRaw";

/**
 * Entity types whose title and description come straight from the localization
 * tables (monsters: the name only).
 */
export const LOCALIZATION_HISTORY_TYPES: readonly VersionedEntityType[] = ["card", "relic", "potion", "enchantment", "monster"];

/**
 * Text before this version was not pinned per locale. Older Compendium
 * versions show a non-Korean locale's earliest pinned text and are marked.
 * This is the oldest archived build; the history needs no authored diffs from here on.
 */
export const LOCALE_TEXT_PINNED_FROM = "0.98.0";

export { VERSION_TEXT_UNPINNED_FIELD } from "./entity-versioning";

const TEXT_FIELD_OF: Record<string, TrackedField> = {
  name: "name",
  description: "descriptionRaw",
  descriptionRaw: "descriptionRaw",
};

/**
 * Entities carry the English text next to the selected locale's, so every
 * locale's API also shows the old English wording: nameEn and descriptionRawEn
 * follow the English history.
 */
const ENGLISH_FIELD_OF: Record<string, TrackedField> = {
  nameEn: "name",
  descriptionRawEn: "descriptionRaw",
};
const ENGLISH_FIELD_FOR: Record<TrackedField, string> = {
  name: "nameEn",
  descriptionRaw: "descriptionRawEn",
};

function bareVersion(patch: string): string {
  return patch.replace(/^v/, "");
}

/**
 * Rewrite version diffs for one game locale.
 *
 * Authored diffs keep wording only in Korean. Inside the pinned range, text
 * diffs come from the locale's history instead, Korean included. Before it,
 * Korean keeps the authored text; other locales use the diff's
 * beforeByLocale text when it has one, and otherwise drop it and get a marker.
 */
export function localizeVersionDiffs(
  base: readonly EntityVersionDiff[],
  locale: GameLocale,
  history: LocalizationHistory,
): EntityVersionDiff[] {
  const localeText = history.text[locale] ?? {};
  const untracked = history.untracked[locale] ?? {};
  const tracked = (type: VersionedEntityType, id: string, field: TrackedField) =>
    LOCALIZATION_HISTORY_TYPES.includes(type) && !untracked[type]?.includes(`${id}.${field}`);
  const englishUntracked = history.untracked.eng ?? {};
  const englishTracked = (type: VersionedEntityType, id: string, field: TrackedField) =>
    LOCALIZATION_HISTORY_TYPES.includes(type) && !englishUntracked[type]?.includes(`${id}.${field}`);

  const localized: EntityVersionDiff[] = base.map((entry) => {
    const pinned = compareVersions(bareVersion(entry.patch), history.pinnedFrom) > 0;
    // Before the pinned range, an authored diff may carry the old game text per
    // locale (beforeByLocale, e.g. backfilled from an older build). Then the
    // locale gets that template and the baked text is rebaked from it.
    const backfilled = new Set(
      entry.diffs
        .filter((diff) => !pinned && locale !== "kor" && diff.beforeByLocale?.[locale] !== undefined)
        .map((diff) => TEXT_FIELD_OF[diff.field]),
    );
    let unpinned = false;
    const diffs = entry.diffs.flatMap((diff): EntityFieldDiff[] => {
      const englishField = ENGLISH_FIELD_OF[diff.field];
      if (englishField) return pinned && englishTracked(entry.entityType, entry.entityId, englishField) ? [] : [diff];
      const field = TEXT_FIELD_OF[diff.field];
      if (!field) return [diff];
      if (pinned && tracked(entry.entityType, entry.entityId, field)) return [];
      if (locale === "kor") return [diff];
      const localBefore = diff.beforeByLocale?.[locale];
      if (localBefore !== undefined) return [{ field: diff.field, before: localBefore, after: null }];
      if (!pinned && !backfilled.has(field)) unpinned = true;
      return [];
    });
    if (unpinned) {
      diffs.push({ field: VERSION_TEXT_UNPINNED_FIELD, before: true, after: null } as EntityFieldDiff);
    } else if (backfilled.has("descriptionRaw")) {
      // This patch's old text is known for the locale, so older versions are
      // pinned again even if a newer patch's text was not.
      diffs.push({ field: VERSION_TEXT_UNPINNED_FIELD, before: false, after: null } as EntityFieldDiff);
    }
    return { ...entry, diffs };
  });

  for (const { entityType, entityId, patch, field, before, after } of history.varDiffs ?? []) {
    localized.push({ entityType, entityId, patch, diffs: [{ field, before, after }] });
  }

  const pushTimelines = (
    source: NonNullable<LocalizationHistory["text"][GameLocale]>,
    fieldName: (field: TrackedField) => string,
  ) => {
    for (const [type, ids] of Object.entries(source) as [VersionedEntityType, Record<string, Partial<Record<TrackedField, [string, string][]>>>][]) {
      for (const [id, fields] of Object.entries(ids)) {
        for (const [field, timeline] of Object.entries(fields) as [TrackedField, [string, string][]][]) {
          for (let index = 1; index < timeline.length; index += 1) {
            const [version, after] = timeline[index];
            localized.push({
              entityType: type,
              entityId: id,
              patch: `v${version}`,
              diffs: [{ field: fieldName(field), before: timeline[index - 1][1], after } as EntityFieldDiff],
            });
          }
        }
      }
    }
  };
  pushTimelines(localeText, (field) => field);
  pushTimelines(history.text.eng ?? {}, (field) => ENGLISH_FIELD_FOR[field]);
  return localized;
}
